package com.mobile.nodeide;
import android.os.Bundle;import android.view.*;import android.widget.*;import android.text.*;import androidx.annotation.*;import androidx.appcompat.app.AlertDialog;import androidx.fragment.app.Fragment;import androidx.recyclerview.widget.*;import java.io.*;import java.util.*;

public class IdeFragment extends Fragment {
 MainActivity a; CodeEditor editor; RecyclerView tree; Rows rows; LinearLayout tabs,panel; TextView output; EditText command; File current; final List<File> visible=new ArrayList<>(), opened=new ArrayList<>(); final Set<String> expanded=new HashSet<>(); boolean loading,dirty; String saved=""; final Deque<String> undo=new ArrayDeque<>(), redo=new ArrayDeque<>(); String previous=""; Process shell; BufferedWriter shellInput;
 public View onCreateView(@NonNull LayoutInflater inflater,ViewGroup container,Bundle state){
  View v=inflater.inflate(R.layout.fragment_ide,container,false);a=(MainActivity)requireActivity(); if(a.project==null){a.show(new ProjectsFragment());return v;}
  editor=v.findViewById(R.id.editor);editor.setCompletionEnabled(a.getPreferences(0).getBoolean("autocomplete",false));tree=v.findViewById(R.id.tree);tabs=v.findViewById(R.id.tabs);panel=v.findViewById(R.id.terminalPanel);output=v.findViewById(R.id.output);command=v.findViewById(R.id.command);
  tree.setLayoutManager(new LinearLayoutManager(a));rows=new Rows(n->{File f=visible.get(n);if(f.isDirectory()){if(!expanded.add(f.getAbsolutePath()))expanded.remove(f.getAbsolutePath());refreshTree();}else open(f);});tree.setAdapter(rows);expanded.add(a.project.getAbsolutePath());refreshTree();
  LinearLayout bar=v.findViewById(R.id.toolbar);button(bar,"‹",()->a.show(new ProjectsFragment()));button(bar,"📁",()->tree.setVisibility(tree.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));button(bar,"✦",()->{save();a.show(new AgentFragment());});button(bar,"▶",()->run("node server.js"));button(bar,"▣",()->panel.setVisibility(panel.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));button(bar,"⚙",this::settings);button(bar,"↶",()->history(undo,redo));button(bar,"↷",()->history(redo,undo));
  LinearLayout quick=v.findViewById(R.id.quick);button(quick,"＋ Arquivo",this::newFile);button(quick,"▣ Salvar",this::save);button(quick,"⌕ Buscar",this::find);button(quick,"⌘ Comandos",()->{panel.setVisibility(View.VISIBLE);command.requestFocus();});button(quick,"■ Parar shell",this::stopShell);
  LinearLayout symbols=v.findViewById(R.id.symbols);for(String s:new String[]{"{","}","[","]","(",")","\"","'",";",":","<",">","←","→"})button(symbols,s,()->{int start=Math.max(0,editor.getSelectionStart());if(s.equals("←"))editor.setSelection(Math.max(0,start-1));else if(s.equals("→"))editor.setSelection(Math.min(editor.length(),start+1));else editor.getText().insert(start,s);});
  editor.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){if(!loading){dirty=true;if(!previous.equals(s.toString())){undo.push(previous);while(undo.size()>100)undo.removeLast();redo.clear();previous=s.toString();}}}public void afterTextChanged(Editable e){}});
  v.findViewById(R.id.execute).setOnClickListener(w->{String cmd=command.getText().toString().trim();if(!cmd.isEmpty()){command.setText("");run(cmd);}});
  View handle=v.findViewById(R.id.handle);handle.setOnTouchListener(new View.OnTouchListener(){float y;int height;public boolean onTouch(View view,android.view.MotionEvent e){if(e.getAction()==0){y=e.getRawY();height=panel.getHeight();return true;}if(e.getAction()==1||e.getAction()==2){int max=((View)panel.getParent()).getHeight()-150;panel.getLayoutParams().height=Math.max(60,Math.min(max,height+(int)(y-e.getRawY())));panel.requestLayout();return true;}return false;}});
  output.setText("Shell Android persistente • comandos no diretório do projeto\nNode.js/npm não estão incluídos. Use Parar shell para interromper.\n");File first=new File(a.project,"server.js");if(first.isFile())open(first); return v;
 }
 void button(LinearLayout row,String label,Runnable r){TextView t=new TextView(a);t.setText(label);t.setTextColor(0xffddd9ed);t.setTextSize(15);t.setGravity(Gravity.CENTER);t.setPadding(13,0,13,0);t.setOnClickListener(v->r.run());row.addView(t,new LinearLayout.LayoutParams(-2,-1));}
 void refreshTree(){visible.clear();List<String> labels=new ArrayList<>();addTree(a.project,0,labels);rows.set(labels);}
 void addTree(File f,int depth,List<String> labels){visible.add(f);StringBuilder pre=new StringBuilder();for(int n=0;n<depth;n++)pre.append("  ");labels.add(pre+(f.isDirectory()?(expanded.contains(f.getAbsolutePath())?"▾ 📁 ":"▸ 📁 "):"  ")+f.getName());if(f.isDirectory()&&expanded.contains(f.getAbsolutePath())&&depth<20){File[] children=f.listFiles();if(children!=null){Arrays.sort(children,(x,y)->x.isDirectory()!=y.isDirectory()?(x.isDirectory()?-1:1):x.getName().compareToIgnoreCase(y.getName()));for(File child:children)addTree(child,depth+1,labels);}}}
 void open(File f){if(f.length()>2_000_000){a.message("Arquivo grande demais para o editor");return;}if(!save())return;try{String text=MainActivity.read(f);current=f;saved=text;loading=true;editor.setFilename(f.getName());editor.setText(text);loading=false;dirty=false;previous=text;undo.clear();redo.clear();if(!opened.contains(f))opened.add(f);renderTabs();}catch(IOException e){loading=false;a.message("Não foi possível abrir: "+e.getMessage());}}
 void renderTabs(){tabs.removeAllViews();for(File f:opened)button(tabs,(f.equals(current)?"● ":"")+f.getName(),()->open(f));}
 boolean save(){if(current==null||!dirty)return true;try{MainActivity.write(current,editor.getText().toString());saved=editor.getText().toString();dirty=false;return true;}catch(IOException e){a.message("Erro ao salvar: "+e.getMessage());return false;}}
 void newFile(){EditText input=new EditText(a);input.setHint("caminho relativo, ex: src/app.js");new AlertDialog.Builder(a).setTitle("Novo arquivo").setView(input).setPositiveButton("Criar",(d,w)->{try{File f=new File(a.project,input.getText().toString());String root=a.project.getCanonicalPath()+File.separator;if(!f.getCanonicalPath().startsWith(root)||f.exists())throw new IOException("Caminho inválido ou arquivo já existente");MainActivity.write(f,"");refreshTree();open(f);}catch(IOException e){a.message(e.getMessage());}}).setNegativeButton("Cancelar",null).show();}
 void find(){EditText input=new EditText(a);input.setHint("Texto");new AlertDialog.Builder(a).setTitle("Pesquisar no arquivo").setView(input).setPositiveButton("Buscar",(d,w)->{String q=input.getText().toString();int n=editor.getText().toString().indexOf(q,Math.max(0,editor.getSelectionEnd()));if(n<0)n=editor.getText().toString().indexOf(q);if(n>=0&&!q.isEmpty()){editor.requestFocus();editor.setSelection(n,n+q.length());}else a.message("Não encontrado");}).setNegativeButton("Cancelar",null).show();}
 void settings(){boolean enabled=a.getPreferences(0).getBoolean("autocomplete",false);new AlertDialog.Builder(a).setTitle("Editor").setMultiChoiceItems(new String[]{"Autocompletar palavras-chave"},new boolean[]{enabled},(d,n,checked)->{a.getPreferences(0).edit().putBoolean("autocomplete",checked).apply();editor.setCompletionEnabled(checked);}).setPositiveButton("Fechar",null).show();}
 void history(Deque<String> from,Deque<String> to){if(from.isEmpty()||current==null)return;to.push(editor.getText().toString());String text=from.pop();loading=true;editor.setText(text);editor.setSelection(editor.length());loading=false;previous=text;dirty=!text.equals(saved);}
 synchronized void stopShell(){if(shell!=null){shell.destroy();shell=null;shellInput=null;}if(output!=null)output.append("\n[Shell encerrado]\n");}
 void run(String cmd){if(!save())return;panel.setVisibility(View.VISIBLE);output.append("\n$ "+cmd+"\n");try{if(shell==null||!shell.isAlive()){Process p=new ProcessBuilder("/system/bin/sh").directory(a.project).redirectErrorStream(true).start();shell=p;shellInput=new BufferedWriter(new OutputStreamWriter(p.getOutputStream()));new Thread(()->{try{char[] buf=new char[1024];try(Reader r=new InputStreamReader(p.getInputStream())){int n;while((n=r.read(buf))!=-1){String chunk=new String(buf,0,n);a.runOnUiThread(()->{if(isAdded())output.append(chunk);});}}int code=p.waitFor();a.runOnUiThread(()->{if(isAdded()){output.append("\n[Shell saiu: "+code+"]\n");refreshTree();}});}catch(Exception e){a.runOnUiThread(()->{if(isAdded())output.append("\nErro: "+e.getMessage()+"\n");});}}).start();}shellInput.write(cmd);shellInput.newLine();shellInput.flush();}catch(IOException e){output.append("Erro: "+e.getMessage()+"\n");}}
 @Override public void onDestroyView(){stopShell();super.onDestroyView();}
 @Override public void onPause(){save();super.onPause();}
}
